-- TASK-205: 48 independent V3 attestation-style exercises, 40 Y1 / 4 Y2 / 4 Y3. Unpublished.
BEGIN;
DO $block$
DECLARE q jsonb;qid uuid;cid uuid;sid uuid;lid uuid; oid uuid;vals jsonb;rightids jsonb;leftids jsonb;keyval jsonb;idx int;item text;v jsonb; ord_ids jsonb;
BEGIN
SELECT id INTO sid FROM public.subjects WHERE code='informatika';
IF sid IS NULL THEN RAISE EXCEPTION 'Missing subject'; END IF;
FOR q IN SELECT value FROM jsonb_array_elements('[{"id":"ALG-V3-A001","group":"A","fmt":"Y1","q":"Shart keyin tekshiriluvchi «gacha» siklida tana kamida necha marta bajariladi?","o":["0 marta","1 marta","2 marta","Faqat shart rost bo‘lsa"],"a":1,"e":"Shart tana bajarilganidan keyin tekshiriladi.","l":1},{"id":"ALG-V3-A002","group":"A","fmt":"Y1","q":"WHILE siklida boshlang‘ich davom etish sharti yolg‘on bo‘lsa, tana necha marta bajariladi?","o":["2 marta","1 marta","0 marta","Kamida 3 marta"],"a":2,"e":"WHILE shartni tana oldidan tekshiradi.","l":1},{"id":"ALG-V3-A003","group":"A","fmt":"Y1","q":"REPEAT ... UNTIL sharti rost bo‘lgan qadamdan keyin nima bo‘ladi?","o":["Sikl yakunlanadi","Sikl cheksiz davom etadi","Sanagich nollanadi","Tana yana 2 marta bajariladi"],"a":0,"e":"UNTIL chiqish sharti rost bo‘lganda to‘xtaydi.","l":2},{"id":"ALG-V3-A004","group":"A","fmt":"Y1","q":"WHILE sharti qachon davom ettirishga ruxsat beradi?","o":["Shart yolg‘on bo‘lganda","Har qanday boshlanishda","Faqat 1-takrorda","Shart rost bo‘lganda"],"a":3,"e":"WHILE davom etish shartidan foydalanadi.","l":2},{"id":"ALG-V3-A005","group":"A","fmt":"Y1","q":"x:=1; REPEAT x:=x+2 UNTIL x>=7. Yakuniy x nechaga teng?","o":["5","9","7","6"],"a":2,"e":"x ketma-ket 3,5,7 ga o‘tadi; 7 da chiqish sharti rost.","l":3},{"id":"ALG-V3-A006","group":"A","fmt":"Y1","q":"x:=1; REPEAT x:=x+2 UNTIL x>=7. Tana necha marta ishlaydi?","o":["4","3","2","5"],"a":1,"e":"Bajarilish izi: 1→3→5→7, jami 3 takrorlash.","l":3},{"id":"ALG-V3-A007","group":"A","fmt":"Y1","q":"x:=10; REPEAT x:=x+1 UNTIL x>5. Yakuniy x?","o":["11","10","5","6"],"a":0,"e":"Tana shart tekshirilishidan oldin bir marta ishlaydi.","l":3},{"id":"ALG-V3-A008","group":"A","fmt":"Y1","q":"x:=1; REPEAT x:=x+3 UNTIL x>=10. Yakuniy x?","o":["7","13","9","10"],"a":3,"e":"x=4,7,10, keyin sikldan chiqadi.","l":3},{"id":"ALG-V3-A009","group":"A","fmt":"Y1","q":"P:=1; FOR i:=1..5 DO P:=P*i. Yakuniy P?","o":["24","100","120","60"],"a":2,"e":"1·2·3·4·5=120, boshlang‘ich ko‘paytma P=1.","l":3},{"id":"ALG-V3-A010","group":"A","fmt":"Y1","q":"5,7,9,...,49 ketma-ketligida nechta had bor?","o":["22","23","24","25"],"a":1,"e":"(49−5)/2+1=23, qadam 2.","l":4},{"id":"ALG-V3-A011","group":"A","fmt":"Y1","q":"Birinchi manfiy songacha yig‘iladi (manfiy qiymat qo‘shilmaydi). Kirish 2,0,5,−3,8. Yig‘indi?","o":["7","4","12","5"],"a":0,"e":"2+0+5=7; −3 terminal belgi, 8 o‘qilmaydi.","l":3},{"id":"ALG-V3-A012","group":"A","fmt":"Y1","q":"Birinchi kiritilgan son −6 bo‘lsa, manfiy songacha bo‘lgan yig‘indi?","o":["−6","6","1","0"],"a":3,"e":"S=0 dan boshlanadi; birinchi son terminal, qo‘shilmaydi.","l":3},{"id":"ALG-V3-A013","group":"A","fmt":"Y1","q":"Sentinel (tugatish belgisi) nima uchun yig‘indiga kiritilmaydi?","o":["Chunki doim 0 ga teng","U natija emas, kiritishni to‘xtatish sharti","Chunki eng katta son","Chunki hisoblagich qiymati"],"a":1,"e":"Manfiy belgi birinchi manfiy qiymatgacha yig‘ishni tugatadi.","l":2},{"id":"ALG-V3-A014","group":"A","fmt":"Y1","q":"Ko‘paytmani jamlab boruvchi P ning odatiy boshlang‘ich qiymati qaysi?","o":["1","0","−1","P oldindan aniqlanmaydi"],"a":0,"e":"1 ko‘paytmaning neytral elementi.","l":1},{"id":"ALG-V3-A015","group":"A","fmt":"Y1","q":"Yig‘indini jamlab boruvchi S ning odatiy boshlang‘ich qiymati?","o":["1","−1","0","2"],"a":2,"e":"0 qo‘shishning neytral elementi.","l":1},{"id":"ALG-V3-A016","group":"A","fmt":"Y1","q":"i:=0; REPEAT i:=i+1 UNTIL i>=3. Yakuniy i?","o":["4","2","1","3"],"a":3,"e":"i=1,2,3 bo‘lganda shart tekshiriladi.","l":3},{"id":"ALG-V3-A017","group":"A","fmt":"Y1","q":"x:=3; REPEAT x:=x−2 UNTIL x<0. Necha takrorlash?","o":["1","2","3","4"],"a":1,"e":"x=1, so‘ng x=−1; 2 ta takrorlash.","l":4},{"id":"ALG-V3-A018","group":"A","fmt":"Y1","q":"S:=0; i:=1; REPEAT S:=S+i; i:=i+1 UNTIL i>4. Yakuniy S?","o":["6","15","10","4"],"a":2,"e":"1+2+3+4=10, i=5 da chiqadi.","l":4},{"id":"ALG-V3-A019","group":"A","fmt":"Y1","q":"i:=5; WHILE i<5 DO i:=i+1. Tana takrorlanishlari soni?","o":["0","1","5","Cheksiz"],"a":0,"e":"5<5 boshidan yolg‘on.","l":2},{"id":"ALG-V3-A020","group":"A","fmt":"Y1","q":"FOR i:=4..9 sikl tanasi nechta marta bajariladi (chegaralar ham kiradi)?","o":["5","7","4","6"],"a":3,"e":"9−4+1=6, har ikki chegara kiradi.","l":3},{"id":"ALG-V3-A021","group":"A","fmt":"Y2","q":"Uch xil siklni shartni tekshirish usuli bilan moslashtiring.","left":["TOKI / WHILE","TAKRORLA ... GACHA / UNTIL","PARAMETR A DAN B GACHA"],"right":["Oldin tekshiradi","Keyin tekshiradi","Qadamlar oralig‘i bo‘yicha yuradi"],"pairs":[[0,0],[1,1],[2,2]],"e":"WHILE oldin, UNTIL keyin, FOR parametr qiymatlari bilan boshqariladi.","l":3},{"id":"ALG-V3-A022","group":"A","fmt":"Y2","q":"Sikl xossasini natija bilan moslang.","left":["WHILE: boshlang‘ich shart yolg‘on","UNTIL: boshlang‘ich shart rost","FOR i=2..4 (qadam 1)"],"right":["0 marta bajarish","Kamida 1 marta bajarish","3 marta bajarish"],"pairs":[[0,0],[1,1],[2,2]],"e":"Shartning tanadan oldin/keyin kelishi va inclusive chegaralar ta’sir qiladi.","l":3},{"id":"ALG-V3-A023","group":"A","fmt":"Y3","q":"x=1 bo‘lganda, x:=x+2 amali va x>=7 chiqish shartining 3 tekshiruvi natijalarini vaqt bo‘yicha tartiblang.","left":["x=7, shart rost","x=3, shart yolg‘on","x=5, shart yolg‘on"],"order":[1,2,0],"e":"1→3→5→7; shart 7 da rost.","l":4},{"id":"ALG-V3-A024","group":"A","fmt":"Y3","q":"Birinchi manfiy songacha yig‘uvchi algoritmdagi amallarni to‘g‘ri tartiblang.","left":["A ni kiritish","A manfiy bo‘lsa sikldan chiqish, aks holda S ga qo‘shish","S:=0 bilan boshlash","S ni chiqarish"],"order":[2,0,1,3],"e":"Yig‘indini boshlash, o‘qish, terminalni tekshirish, chiqarish.","l":4},{"id":"ALG-V3-B001","group":"B","fmt":"Y1","q":"Algoritm nima?","o":["Faqat dasturlash tili","Ijrochi uchun aniq ko‘rsatmalar ketma-ketligi","Faqat ma’lumotlar bazasi","Kompyuterning xotirasi"],"a":1,"e":"Ijrochi bajaradigan aniq ko‘rsatmalar ketma-ketligi.","l":1},{"id":"ALG-V3-B002","group":"B","fmt":"Y1","q":"Blok-sxemadagi romb odatda nimani anglatadi?","o":["Natijani chiqarish","Yangi fayl yaratish","Shartni tekshirish","Tugatish"],"a":2,"e":"Romb — shart/qaror.","l":1},{"id":"ALG-V3-B003","group":"B","fmt":"Y1","q":"Blok-sxemada kiritish yoki chiqarish uchun qaysi shakl qo‘llanadi?","o":["Oval","Romb","To‘g‘ri to‘rtburchak","Parallelogramm"],"a":3,"e":"Kiritish/chiqarish parallelogramm.","l":1},{"id":"ALG-V3-B004","group":"B","fmt":"Y1","q":"Blok-sxemadagi oval qanday vazifa bajaradi?","o":["Boshlash yoki tugatish","Shart tekshirish","Ko‘paytirish","Ma’lumot kiritish"],"a":0,"e":"Oval start/end uchun.","l":1},{"id":"ALG-V3-B005","group":"B","fmt":"Y1","q":"Shartsiz ketma-ket bajariladigan amallardan iborat tuzilma?","o":["Aralash","Chiziqli","Takrorlanuvchi","Tarmoqlanuvchi"],"a":1,"e":"Chiziqli algoritm amallari shartsiz tartibda bajariladi.","l":1},{"id":"ALG-V3-B006","group":"B","fmt":"Y1","q":"Bir sikl ichida IF sharti ishlatilsa, bu qanday tuzilma?","o":["Faqat chiziqli","Faqat ma’lumot saqlash","Faqat kiritish","Aralash: takrorlash va tarmoqlanish"],"a":3,"e":"Bir nechta tuzilma birgalikda ishlagan.","l":2},{"id":"ALG-V3-B007","group":"B","fmt":"Y1","q":"FOR i:=1..3 DO FOR j:=1..2 DO CHIQAR(i,j). Nechta juftlik?","o":["5","9","6","8"],"a":2,"e":"3 ta tashqi, 2 ta ichki → jami 6.","l":3},{"id":"ALG-V3-B008","group":"B","fmt":"Y1","q":"FOR i:=1..4 DO FOR j:=1..i DO K:=K+1, K boshida 0. Yakuniy K?","o":["10","12","8","16"],"a":0,"e":"1+2+3+4=10.","l":4},{"id":"ALG-V3-B009","group":"B","fmt":"Y1","q":"S:=0; FOR i:=1..5 DO IF i mod 2<>0 THEN S:=S+i*i. S?","o":["25","35","45","55"],"a":1,"e":"Toq qiymatlar 1,3,5: 1²+3²+5²=35.","l":3},{"id":"ALG-V3-B010","group":"B","fmt":"Y1","q":"FOR i:=1..6 DO IF i mod 2=0 THEN K:=K+1, K=0. K?","o":["6","3","2","4"],"a":1,"e":"2,4,6 uchun 3 marta oshadi.","l":3},{"id":"ALG-V3-B011","group":"B","fmt":"Y1","q":"Faqat −7, −2, −9 ichidagi eng kattasi?","o":["−7","0","−2","−9"],"a":2,"e":"−2 qolgan ikkitasidan katta.","l":2},{"id":"ALG-V3-B012","group":"B","fmt":"Y1","q":"Faqat manfiy sonlar maksimumini topishda max:=0 boshlanishining xatosi?","o":["Natija ro‘yxatda bo‘lmagan 0 bo‘lib qolishi mumkin","Takrorlashlar doim 0 bo‘ladi","Eng kichik son oshib ketadi","Har bir son 2 marta sanaladi"],"a":0,"e":"Birinchi elementdan boshlash xavfsiz.","l":3},{"id":"ALG-V3-B013","group":"B","fmt":"Y1","q":"Faqat x>0 va x<0 holatlarini tekshirgan algoritm qaysi kirishni alohida ko‘rmagan?","o":["x=3","x=−1","x=100","x=0"],"a":3,"e":"0 na musbat, na manfiy.","l":2},{"id":"ALG-V3-B014","group":"B","fmt":"Y1","q":"a:=3; b:=8; t:=a; a:=b; b:=t. Yakunda (a,b)?","o":["(3,8)","(8,3)","(8,8)","(3,3)"],"a":1,"e":"Vaqtincha t orqali qiymatlar almashtiriladi.","l":3},{"id":"ALG-V3-B015","group":"B","fmt":"Y1","q":"18 va 12 ning EKUBi Yevklid usulida nechaga teng?","o":["3","12","6","2"],"a":2,"e":"18−12=6; 12−6=6, natija 6.","l":3},{"id":"ALG-V3-B016","group":"B","fmt":"Y1","q":"1 dan 10 gacha natural sonlar yig‘indisi?","o":["45","50","60","55"],"a":3,"e":"10·11/2=55.","l":2},{"id":"ALG-V3-B017","group":"B","fmt":"Y1","q":"Saralanmagan ro‘yxatda element mavjudligini tekshirish uchun qaysi umumiy usul ishlaydi?","o":["Elementlarni ketma-ket tekshirish","Faqat ikkilik qidiruv","Faqat graf chizish","Faqat ko‘paytirish"],"a":0,"e":"Chiziqli qidiruv saralashni talab qilmaydi.","l":3},{"id":"ALG-V3-B018","group":"B","fmt":"Y1","q":"Ikkilik qidiruvdan to‘g‘ri foydalanish uchun eng zarur shart?","o":["Raqamlar 10 dan oshmasin","Ro‘yxat faqat manfiy bo‘lsin","Ro‘yxat tartiblangan bo‘lsin","Har bir element 0 bo‘lsin"],"a":2,"e":"Oraliqni ikkiga bo‘lish uchun tartib zarur; bu qo‘shimcha mavzu.","l":3},{"id":"ALG-V3-B019","group":"B","fmt":"Y1","q":"1..n yig‘indisini n juda katta bo‘lsa tez hisoblash uchun qaysi yondashuv qulay?","o":["Har qiymatni tasodifiy o‘zgartirish","S:=S+1 ni n marta bajarish","Sonlarni grafikda chizish","n(n+1)/2 formulasidan foydalanish"],"a":3,"e":"Formula doimiy miqdordagi asosiy amal talab qiladi (mos butun n uchun).","l":4},{"id":"ALG-V3-B020","group":"B","fmt":"Y1","q":"x:=3; WHILE x<20 DO x:=2*x. Tana necha marta bajariladi?","o":["3","4","2","5"],"a":0,"e":"3→6→12→24, x<20 sharti 24 da yolg‘on; 3 takror.","l":4},{"id":"ALG-V3-B021","group":"B","fmt":"Y2","q":"Blok-sxema belgisini vazifasi bilan moslang.","left":["Oval","Romb","Parallelogramm"],"right":["Boshlash/yakunlash","Shartni tekshirish","Kiritish/chiqarish"],"pairs":[[0,0],[1,1],[2,2]],"e":"Standart shakllarning funksiyasi farq qiladi.","l":3},{"id":"ALG-V3-B022","group":"B","fmt":"Y2","q":"Masalani mos algoritm yondashuvi bilan juftlang.","left":["Ikki natural sonning EKUBi","Tartiblanmagan ro‘yxatdan element izlash","1 dan n gacha sonlar yig‘indisi"],"right":["Yevklid usuli","Ketma-ket ko‘rib chiqish","n(n+1)/2 formulasi"],"pairs":[[0,0],[1,1],[2,2]],"e":"Masalaning aniq sharti mos usulni belgilaydi.","l":3},{"id":"ALG-V3-B023","group":"B","fmt":"Y3","q":"Masaladan ishlaydigan algoritmga o‘tish bosqichlarini to‘g‘ri tartiblang.","left":["Algoritmni sinov qiymatlarida tekshirish","Kirish, chiqish va maqsadni aniqlash","Amallar va shartlarni tuzish","Natijani taqdim etish"],"order":[1,2,0,3],"e":"Avval masala modeli, keyin amallar, sinov va natija.","l":4},{"id":"ALG-V3-B024","group":"B","fmt":"Y3","q":"18 va 12 sonlarida ayirishli Yevklid jarayoni holatlarini tartiblang.","left":["(6,6), natija 6","(18,12), boshlanish","(6,12), birinchi ayirish"],"order":[1,2,0],"e":"18−12=6, so‘ng 12−6=6.","l":4}]'::jsonb) LOOP
 SELECT id INTO cid FROM public.constructs WHERE code=CASE WHEN q->>'group'='A' THEN 'S3.ALGO.02' ELSE 'S3.ALGO.03' END;
 SELECT id INTO lid FROM public.lessons WHERE slug=CASE WHEN q->>'group'='A' THEN 'algoritmlash-v3-shart-keyin-sikl' ELSE 'algoritmlash-v3-ijro-iz-va-test-uslubi' END AND status='review';
 IF cid IS NULL OR lid IS NULL THEN RAISE EXCEPTION 'Missing V3 lesson/construct %',q->>'id'; END IF;
 IF EXISTS(SELECT 1 FROM public.questions WHERE source_reference='algoritmlash-v3:'||(q->>'id')) THEN CONTINUE; END IF;
 qid:=gen_random_uuid();
 INSERT INTO public.questions(id,subject_id,construct_id,group_code,format,cognitive,difficulty,stem_md,assets,is_generated,status,source_reference,source_lesson_id)
 VALUES(qid,sid,cid,'S3.ALGO',(q->>'fmt')::question_format,
 (CASE WHEN (q->>'l')::int<=2 THEN 'bilish' WHEN (q->>'l')::int=3 THEN 'qollash' ELSE 'mulohaza' END)::cognitive_level,
 (q->>'l')::int,q->>'q','[]'::jsonb,true,'review'::content_status,'algoritmlash-v3:'||(q->>'id'),lid);
 leftids:='[]'::jsonb;rightids:='[]'::jsonb;
 IF q->>'fmt'='Y1' THEN
  FOR v IN SELECT value FROM jsonb_array_elements(q->'o') WITH ORDINALITY LOOP
   NULL; 
  END LOOP;
  FOR item,idx IN SELECT value, (ordinality::int-1) FROM jsonb_array_elements_text(q->'o') WITH ORDINALITY LOOP
   oid:=gen_random_uuid();INSERT INTO public.question_options(id,question_id,side,order_idx,content_md) VALUES(oid,qid,'a',idx,item);
   leftids:=leftids||jsonb_build_array(oid::text);
  END LOOP;
  keyval:=jsonb_build_object('correct_option_id',leftids->>(q->>'a')::int);
 ELSE
  FOR item,idx IN SELECT value,(ordinality::int-1) FROM jsonb_array_elements_text(q->'left') WITH ORDINALITY LOOP
   oid:=gen_random_uuid();INSERT INTO public.question_options(id,question_id,side,order_idx,content_md) VALUES(oid,qid,'a',idx,item);
   leftids:=leftids||jsonb_build_array(oid::text);
  END LOOP;
  IF q->>'fmt'='Y2' THEN
   FOR item,idx IN SELECT value,(ordinality::int-1) FROM jsonb_array_elements_text(q->'right') WITH ORDINALITY LOOP
    oid:=gen_random_uuid();INSERT INTO public.question_options(id,question_id,side,order_idx,content_md) VALUES(oid,qid,'b',idx,item);
    rightids:=rightids||jsonb_build_array(oid::text);
   END LOOP;
   vals:='{}'::jsonb;
   FOR v IN SELECT value FROM jsonb_array_elements(q->'pairs') LOOP
    vals:=vals||jsonb_build_object(leftids->>(v->>0)::int,rightids->>(v->>1)::int);
   END LOOP;
   keyval:=jsonb_build_object('pairs',vals);
  ELSE
   ord_ids:='[]'::jsonb;
   FOR v IN SELECT value FROM jsonb_array_elements(q->'order') LOOP
    ord_ids:=ord_ids||jsonb_build_array(leftids->>(v::text)::int);
   END LOOP;
   keyval:=jsonb_build_object('order',ord_ids);
  END IF;
 END IF;
 INSERT INTO public.question_keys(question_id,payload,explanation_md) VALUES(qid,keyval,(q->>'e')||E'\n\nV3 manba/uslub: 9-sinf ICT PDF 41–46, 2026 spesifikatsiya PDF 4; Test.pdf PDF 53–63 dagi savol-uslubidan ilhomlangan original mashq.');
END LOOP;
IF (SELECT count(*) FROM public.questions WHERE source_reference LIKE 'algoritmlash-v3:ALG-V3-%')<>48 THEN RAISE EXCEPTION 'V3 total mismatch'; END IF;
END $block$;
COMMIT;